var (
	// ErrShort reports a message shorter than its layout.
	ErrShort = fixsbe.ErrShort
	// ErrSchema reports a message of another schema.
	ErrSchema = fixsbe.ErrSchema
	// ErrTemplate reports a message of another template.
	ErrTemplate = fixsbe.ErrTemplate
	// ErrMalformed reports a message whose structure is not the schema's.
	ErrMalformed = fixsbe.ErrMalformed
	// ErrLength reports data shorter or longer than its length allows.
	ErrLength = fixsbe.ErrLength
	// ErrEntries reports a group entry count out of its bounds, or beyond MaxEntries.
	ErrEntries = fixsbe.ErrEntries
	// ErrNewer reports a message of a newer version than the schema's that
	// holds groups or data the schema does not know, or may hold them where
	// nothing tells, or whose counts of them contradict the schema: what
	// follows cannot be found with certainty.
	ErrNewer = fixsbe.ErrNewer
)

// Some returns v, not null.
func Some[T any](v T) Optional[T] { return fixsbe.Some(v) }

// ReadHeader decodes the message header at the start of b, and returns the
// message body after it.
func ReadHeader(b []byte) (MessageHeader, []byte, error) { return fixsbe.ReadHeader(b) }
